import{_ as t,o as e,c as i,an as n}from"./chunks/framework.Y04DxkVZ.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"HeatExchange.jl","text":"Heat and water budgets of organisms","tagline":"solve for the body temperature, or for the metabolic rate, of an animal or a leaf exchanging heat with its environment by radiation, convection, conduction and evaporation, with units.","actions":[{"theme":"brand","text":"Get Started","link":"/get_started"},{"theme":"alt","text":"View on Github","link":"https://github.com/BiophysicalEcology/HeatExchange.jl"},{"theme":"alt","text":"API Reference","link":"/api"}]},"features":[{"title":"⚖️ Heat balance","details":"<a class=\\"highlight-link\\">Solar and longwave radiation, convection, conduction, evaporation, respiration and metabolism</a>, summed into a budget whose residual is zero at steady state.","link":"/manual/heat_balance"},{"title":"🌡️ Temperature or metabolic rate","details":"Find the <a class=\\"highlight-link\\">body temperature</a> for a given metabolism, or the <a class=\\"highlight-link\\">metabolic rate</a> that holds a given core temperature, with bare skin or with insulation.","link":"/manual/solvers"},{"title":"🧥 Fur, feathers and fat","details":"Heat conducted from the core through <a class=\\"highlight-link\\">flesh, fat and a porous coat</a> as a stack of radial layers, with radiation and conduction through the fibres.","link":"/manual/radial_layers"},{"title":"🐕 Bodies of many parts","details":"A back and a belly, or a trunk, head and limbs, each with <a class=\\"highlight-link\\">its own heat budget</a>, sharing a core or conducting heat to each other.","link":"/manual/multipart"},{"title":"🍃 Leaves","details":"The same heat budget with <a class=\\"highlight-link\\">stomatal conductance</a> in place of wet skin, for leaf temperature and transpiration.","link":"/tutorials/leaf"},{"title":"🦎 For NicheMapR users","details":"How the <a class=\\"highlight-link\\">ectotherm and endotherm models of NicheMapR</a> map onto this package, and what has changed.","link":"/manual/nichemapr"},{"title":"📐 Differentiable","details":"Written so that an optimiser can drive the heat budget with <a class=\\"highlight-link\\">automatic differentiation</a>, as BiophysicalBehaviour.jl does.","link":"/manual/autodiff"},{"title":"📏 Units","details":"Every temperature, heat flow and trait is a <a class=\\"highlight-link\\">Unitful.jl</a> quantity.","link":"/manual/introduction"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),s={name:"index.md"};function l(o,a,h,r,c,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h2 id="How-to-install-HeatExchange.jl?" tabindex="-1">How to install HeatExchange.jl? <a class="header-anchor" href="#How-to-install-HeatExchange.jl?" aria-label="Permalink to &quot;How to install HeatExchange.jl? {#How-to-install-HeatExchange.jl?}&quot;">​</a></h2><p>HeatExchange.jl can be installed from the Julia REPL:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/BiophysicalEcology/HeatExchange.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="Manual" tabindex="-1">Manual <a class="header-anchor" href="#Manual" aria-label="Permalink to &quot;Manual {#Manual}&quot;">​</a></h2><p>HeatExchange.jl computes the exchange of heat, and of the water that goes with it, between an organism and its environment. Given the organism&#39;s size, shape, surface properties and physiology, and the air temperature, wind, humidity and radiation around it, it solves the steady-state heat budget for the body temperature, or for the metabolic rate needed to hold a body temperature.</p><p>It is part of the <a href="https://github.com/BiophysicalEcology" target="_blank" rel="noreferrer">BiophysicalEcology</a> ecosystem for mechanistic niche modelling. The bodies come from <a href="https://github.com/BiophysicalEcology/BiophysicalGeometry.jl" target="_blank" rel="noreferrer">BiophysicalGeometry.jl</a>, the environments from <a href="https://github.com/BiophysicalEcology/Microclimate.jl" target="_blank" rel="noreferrer">Microclimate.jl</a>, and the behaviour that changes both from <a href="https://github.com/BiophysicalEcology/BiophysicalBehaviour.jl" target="_blank" rel="noreferrer">BiophysicalBehaviour.jl</a>. See the <a href="./manual/introduction">Introduction</a> for the design of the package, <a href="./manual/ecosystem">Environments and the ecosystem</a> for how the packages fit together, and <a href="./manual/nichemapr">For NicheMapR users</a> for its origin in <a href="https://github.com/mrke/NicheMapR" target="_blank" rel="noreferrer">NicheMapR</a>.</p>`,6)])])}const u=t(s,[["render",l]]);export{g as __pageData,u as default};
